import{c as n,Q as t,j as o,m as s}from"./chunks/framework.BqPkuuVc.js";const a="/assets/docs-reference-extensions-empty.C5jciKSo.png",i="/assets/docs-reference-extensions-list.BJ4WC3Dj.png",r="/assets/docs-reference-extensions-remove-dialog.CRK2Q6uZ.png",x=JSON.parse('{"title":"Installing extensions","description":"","frontmatter":{},"headers":[],"relativePath":"user/advanced/installing-extensions.md","filePath":"user/advanced/installing-extensions.md"}'),h={name:"user/advanced/installing-extensions.md"};function l(d,e,g,c,p,u){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="installing-extensions" tabindex="-1">Installing extensions <a class="header-anchor" href="#installing-extensions" aria-label="Permalink to &quot;Installing extensions&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers who want to add something Manager doesn&#39;t do out of the box, usually a dashboard tile.</p><p>An <em>extension</em> (<a href="./../getting-started/concepts-glossary#extending-manager">glossary</a>) is a small add-on someone has written for Manager, installed from a <code>.zip</code> file. This page covers installing, updating and removing one.</p><h2 id="what-an-extension-is" tabindex="-1">What an extension is <a class="header-anchor" href="#what-an-extension-is" aria-label="Permalink to &quot;What an extension is&quot;">​</a></h2><p>An extension adds a feature without changing Manager itself. Most add a <strong>dashboard tile</strong>: a count, a list, or something fetched from elsewhere, such as entries arriving in a spreadsheet on the day. A tile can open a competitor&#39;s <strong><a href="./../event-setup/competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a></strong> dialog when you click something in it.</p><p>Extensions are not the same as Manager&#39;s built-in features, such as the leaderboard and commentary. Those come with Manager and are always there. An extension is something you choose to add, from whoever wrote it.</p><p><strong>There&#39;s no extension store.</strong> You get an extension from whoever wrote it: your club, another organiser, or someone you&#39;ve asked to build one.</p><blockquote><p><strong>Warning:</strong> An extension is a program. It runs in the browser of everyone who has the event open in Manager, can read the event&#39;s data, and can make requests to websites on the internet (but not to computers on your own network). Install extensions only from people you trust.</p></blockquote><h2 id="the-extensions-page" tabindex="-1">The Extensions page <a class="header-anchor" href="#the-extensions-page" aria-label="Permalink to &quot;The Extensions page&quot;">​</a></h2><p>Open it from the <strong>Extensions</strong> icon at the top of the <strong>Events</strong> list (hover over the icons to find it). It lists every installed extension with its name, description, version and what it adds (such as <strong>Dashboard tile</strong>), and a settings button if it has settings for this computer. Until you install one it says <strong>No extensions installed</strong>.</p><p><img src="'+a+'" alt="The Extensions page with nothing installed: No extensions installed, and Upload extension at the top right"></p><p><img src="'+i+'" alt="The Extensions page with two extensions: each with its name, description, version and a Dashboard tile chip; Late entries sheet also has a settings button, and both have a remove (bin) button"></p><p>The chip says what the extension adds: <strong>Dashboard tile</strong>, <strong>Navigation</strong>, <strong>Screen</strong> or <strong>Event config</strong>. Today only dashboard tiles appear in an event. The back arrow at the top left returns to the <strong>Events</strong> list.</p><p>Extensions belong to this computer, not to an event. Each event chooses which of them it uses (see <a href="./configuring-extensions#using-an-extension-in-an-event">Using an extension in an event</a>).</p><h2 id="installing-one" tabindex="-1">Installing one <a class="header-anchor" href="#installing-one" aria-label="Permalink to &quot;Installing one&quot;">​</a></h2><ol><li>Get the extension&#39;s <code>.zip</code> file.</li><li>On the <strong>Extensions</strong> page, click <strong>Upload extension</strong> and choose the file.</li><li>Manager checks the package and installs it: <em>Extension &quot;name&quot; installed successfully.</em> If the file isn&#39;t a valid extension, it says why with <em>Failed to install extension: …</em> — for example, the <code>.zip</code> has no <code>manifest.json</code>, or no script file named after the extension, at its top level. The file can be up to 10 MB.</li><li>Switch the extension on for each event that should use it, in <strong>Event details → Extensions</strong>. See <a href="./configuring-extensions">Configuring extensions</a>.</li></ol><h2 id="updating-one" tabindex="-1">Updating one <a class="header-anchor" href="#updating-one" aria-label="Permalink to &quot;Updating one&quot;">​</a></h2><p>Upload the newer <code>.zip</code> the same way. An extension with the same name replaces the one installed, and keeps its settings. Reload any browser that has an event open to pick up the new version.</p><h2 id="removing-one" tabindex="-1">Removing one <a class="header-anchor" href="#removing-one" aria-label="Permalink to &quot;Removing one&quot;">​</a></h2><p>Click the extension&#39;s remove button (the bin) on the <strong>Extensions</strong> page and confirm with <strong>Remove</strong>. It&#39;s removed from this computer, and its tiles disappear from every event&#39;s dashboard. This can&#39;t be undone, but you can install it again from its <code>.zip</code>; its settings for this computer, and each event&#39;s settings for it, are kept and come back with it.</p><p><img src="'+r+'" alt="The Remove extension dialog: Are you sure you want to remove Bus count? This cannot be undone. With Cancel and Remove"></p><h2 id="on-another-computer" tabindex="-1">On another computer <a class="header-anchor" href="#on-another-computer" aria-label="Permalink to &quot;On another computer&quot;">​</a></h2><p>Extensions are installed per computer and don&#39;t travel with an event&#39;s backup. If you move an event to another computer, install its extensions there too; the event remembers which ones it uses and their per-event settings. See <a href="./../event-setup/moving-an-event#set-up-what-belongs-to-the-laptop">Moving an event to another computer</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./configuring-extensions">Configuring extensions</a></li><li><a href="./../running-the-event/dashboard">The event dashboard</a></li><li><a href="./../reference/settings">Settings</a></li></ul>',25)])])}const f=n(h,[["render",l]]);export{x as __pageData,f as default};
